mkdir -p test && cat > test/order-total.test.mjs <<'EOF'
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.99, D: 100, E: 101 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function totalFor(items) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  try {
    const base = `http://localhost:${server.address().port}`
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
    assert.equal(res.status, 201)
    const order = await res.json()
    const fetched = await (await fetch(`${base}/orders/${order.id}`)).json()
    assert.equal(fetched.total, order.total)
    return order.total
  } finally {
    server.close()
  }
}

test('small order: no discount', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 3 }]), 30)
})

test('multiple lines are summed', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }]), 71)
})

test('exactly 100 gets no discount (threshold is strictly greater)', async () => {
  assert.equal(await totalFor([{ sku: 'D', qty: 1 }]), 100)
})

test('just over 100 gets 10% off', async () => {
  // 101 - 10.1 = 90.9 -> floored
  assert.equal(await totalFor([{ sku: 'E', qty: 1 }]), 90)
})

test('large order gets 10% off', async () => {
  assert.equal(await totalFor([{ sku: 'D', qty: 10 }]), 900)
})

test('discount applies to whole order, not just the part over 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99)
})

test('total is floored to whole euros (cents are dropped)', async () => {
  // 0.99 * 3 = 2.97 -> 2
  assert.equal(await totalFor([{ sku: 'C', qty: 3 }]), 2)
})

test('empty items rejected', async () => {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const res = await fetch(`http://localhost:${server.address().port}/orders`, { method: 'POST', body: '{"items":[]}' })
  server.close()
  assert.equal(res.status, 400)
})
EOF
